from 写入第二遍 import add
add('09_002',13,'16:9，中景在撤离队前方倒退跟拍。起幅含青梅男、他背上的女主席、右侧青梅女及左后宽帽同行者；青梅女回喊时向她一侧横移，答声后回落到青梅男肩与盔面，三人关系仍同框。','青梅男背着闭眼的女主席持续向前跑，女主席的手臂搭在他肩旁、长发随步幅摆动。青梅女边跑边回头向宽帽同行者高喊，手臂顺跑势后摆；收到答声后把头转回前方，脚步追平青梅男。青梅男肩背忽然绷直，盔面稍向侧下压，随即把背上人托稳继续跑；女主席仍闭眼，身体随他步伐轻颠。','灰米砖路向纵深延伸，后方避难者剪影错落分流，两侧屋脚被前景人物部分遮住。','天空从街巷敞口洒下冷白柔光，盔面反光柔和，帽檐下脸部较暗。','急促脚步有轻重错拍，衣袖与裙摆擦响，人群脚步向不同巷道散开。',japanese=['主席の女性はこちらで面倒を見ます！あなたたちは村人を助けて！','はい！','うっ…彼女の胸が、俺の背中に直接当たってるのを感じる…'],tone='青梅女急而清楚地下达分工；同行者立即应答；青梅男内心短暂局促，脚步不断。',phase='process',kind='mixed',node={'撤离队.阶段':'背人继续撤离并分工'},pcard={'opening':'三人持续跑动，青梅女同时照顾前进与分工。','beats':['青梅女回喊，同行者答后分流','女主席伏肩不醒','青梅男肩背一紧后托稳人继续跑'],'coupling':'答声使青梅女结束回看；内心话不触发旁人回应。','landing':'主队向前，其他人分路救援。'})
add('09_003',1.5,'16:9，低角度近景，青梅男盔面位于左下；从他肩旁向屋檐夹出的天空上摇，落在斜穿天空的两道深色直线与亮色疾掠痕。','青梅男跑动中把盔面抬向头顶偏右的画外天空，肩背随脚步起伏；亮线从屋檐间疾掠，盔旁汗珠拖出一小段，他的头跟到屋檐边便把注意转回前路。','近侧屋檐从画面左上退出，另一侧高墙边缘在右下，铅蓝云层与两道斜向深色线条展开。','盔面上沿接开阔天空冷白柔光，街巷下侧仍较暗。','头顶一声长而尖的掠风，脚步维持节奏，喊声退到远处。',phase='reaction',node={'撤离队.阶段':'注意头顶战斗仍持续前进'},meaning='原格两道深色线条保留为画面轮廓，不将其擅自解释成可攀援电线。')
add('09_004',8,'16:9，广角在青前侧退行跟拍，起幅青占右前景、武士在左后景；相机速度略低于青，让她逼近到胸上近景，随后跟住，屋顶与拱门从下方后退。','青在空中沿屋顶上方前冲，先低眼瞥向下方街道，脸上的急切变成咬牙，收回原本向下落的手，腰身一拧抬高转移路线；长马尾在她头顶扫成大弧。武士从后方追入她腾出的路线，黑外衣扩开，双方距离逐步缩短。青再把眼睛抬向前方空隙，眉头收紧，继续避开屋顶下方的人群。','近层蓝灰屋脊快速退下，稍远的灰米拱门与高低砖屋向两侧分开，远层云天移动较慢；屋顶擦过处有短促米灰尘痕。','破烟囱所在屋面的开阔天空从两人后上方给冷白柔光，青前侧受较弱中性天光。','近处风声加重，瓦面掠过带来短促刷响，武士衣摆破风逐渐逼近；街面呼喊在下方。',japanese=['どこへ走っても、人に囲まれてる…！！','こんな状況で戦うのは危険すぎる…'],tone='急促内心，边判断边换气，嘴不对内心话做说话口型。',phase='process',kind='mixed',node={'青.阶段':'腾空转移避开人群','武士.阶段':'后方追近'},pcard={'opening':'青一边逃开刀路一边寻找落点，注意力被下方人群牵住。','beats':['下瞥、咬牙，取消向下落的趋势','拧腰抬高路线，抬眼寻找前方空隙'],'coupling':'为保护人群而选择路线，使武士获得追近机会。','landing':'青继续在屋顶上空转移，武士已缩短距离。'})
